<!doctype html><html lang="{{ session('portal_lang','en') }}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $order->order_no }}</title><style>body{font:14px system-ui,sans-serif;color:#172033;margin:32px auto;max-width:800px;padding:0 18px}header{border-bottom:2px solid #172033;padding-bottom:18px}h1{margin:0}table{width:100%;border-collapse:collapse;margin:22px 0}td,th{text-align:left;padding:12px 8px;border-bottom:1px solid #ddd}button,a{padding:10px;color:#172033} @media print{.actions{display:none}}</style></head><body><div class="actions"><a href="{{ route('business.customer.orders.show',['order'=>$order->id]) }}">{{ t('Back','ফিরে যান') }}</a><button onclick="window.print()">{{ t('Print / Save PDF','প্রিন্ট / PDF সংরক্ষণ') }}</button></div><header><h1>{{ $business->name }}</h1><h2>{{ t('Order summary','অর্ডার বিবরণ') }} · {{ $order->order_no }}</h2><p>{{ $order->created_at?->format('d M Y') }} · {{ $order->customer_name }}</p><p>{{ $order->customer_address }}</p></header><table><thead><tr><th>{{ t('Product','পণ্য') }}</th><th>{{ t('Quantity','পরিমাণ') }}</th><th>{{ t('Total','মোট') }}</th></tr></thead><tbody>@foreach($order->items as $item)<tr><td>{{ $item->name }}</td><td>{{ $item->quantity+0 }}</td><td>৳{{ number_format($item->line_total,2) }}</td></tr>@endforeach</tbody></table>@foreach(['subtotal'=>['Subtotal','উপমোট'],'discount'=>['Discount','ছাড়'],'shipping'=>['Shipping','ডেলিভারি'],'tax'=>['Tax','কর'],'total'=>['Order total','অর্ডারের মোট'],'paid'=>['Paid','পরিশোধিত'],'credited'=>['Return credit','রিটার্ন ক্রেডিট']] as $key=>$label)<p>{{ t(...$label) }}: <strong>৳{{ number_format($order->$key,2) }}</strong></p>@endforeach</body></html>
